    .aw-header-reference .aw-topbar-inner { padding-inline: 18px; min-height: 40px; gap: 12px; }
    .aw-header-reference .aw-topbar-motto { display: none; }
    .aw-header-reference .aw-topbar-title { font-size: 11px; }
    .aw-header-reference .aw-brand-logo { width: 50px; height: 50px; flex-basis: 50px; border-radius: 14px; }
    .aw-header-reference .aw-brand-logo img { width: 42px; height: 42px; }
    .aw-header-reference .aw-brand-title { font-size: 16px; }
    .aw-header-reference .aw-brand-subtitle { font-size: 11px; }
    .aw-header-reference .aw-mobile-menu { max-height: 75vh; max-height: 75dvh; overflow-y: auto; }
}
.aw-header .aw-hidden { display: none !important; }
/* End navigation editor base */

